fn build_tree(
    dir: &Path,
    max_depth: usize,
    show_hidden: bool,
    prefix: &str,
) -> std::io::Result<(String, bool)> {
    let mut lines = Vec::new();
    let mut truncated = false;
    let name = dir
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| dir.to_string_lossy().to_string());
    lines.push(format!("{prefix}{name}"));
    walk(dir, 0, max_depth, show_hidden, "", &mut lines, &mut truncated)?;
    Ok((lines.join("\n"), truncated))
}

fn walk(
    dir: &Path,
    depth: usize,
    max_depth: usize,
    show_hidden: bool,
    prefix: &str,
    lines: &mut Vec<String>,
    truncated: &mut bool,
) -> std::io::Result<()> {
    let mut entries = Vec::new();
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let name = entry.file_name().to_string_lossy().to_string();
        if !show_hidden && name.starts_with('.') {
            continue;
        }
        entries.push((name, entry.file_type()?));
    }
    // Directories first, then files, both sorted by name.
    entries.sort_by(|a, b| match (a.1.is_dir(), b.1.is_dir()) {
        (true, false) => std::cmp::Ordering::Less,
        (false, true) => std::cmp::Ordering::Greater,
        _ => a.0.cmp(&b.0),
    });

    for (i, (name, file_type)) in entries.iter().enumerate() {
        let is_last = i + 1 == entries.len();
        let connector = if is_last { "└── " } else { "├── " };
        let child_prefix = format!("{prefix}{}", if is_last { "    " } else { "│   " });

        if depth >= max_depth {
            lines.push(format!("{prefix}{connector}{name}"));
            continue;
        }

        lines.push(format!("{prefix}{connector}{name}"));

        if file_type.is_dir() {
            if depth + 1 < max_depth {
                walk(
                    &dir.join(name),
                    depth + 1,
                    max_depth,
                    show_hidden,
                    &child_prefix,
                    lines,
                    truncated,
                )?;
            } else {
                let child_count = fs::read_dir(dir.join(name))?.count();
                if child_count > 0 {
                    lines.push(format!("{child_prefix}… ({child_count} more entries)"));
                    *truncated = true;
                }
            }
        }
    }

    Ok(())
}
